static void free_soc_dts ( struct soc_sensor_entry * aux_entry ) { if ( aux_entry ) { if ( ! aux_entry -> locked ) { mutex_lock ( & dts_update_mutex ) ; iosf_mbi_write ( QRK_MBI_UNIT_RMU , MBI_REG_WRITE , QRK_DTS_REG_OFFSET_ENABLE , aux_entry -> store_dts_enable ) ; iosf_mbi_write ( QRK_MBI_UNIT_RMU , MBI_REG_WRITE , QRK_DTS_REG_OFFSET_PTPS , aux_entry -> store_ptps ) ; mutex_unlock ( & dts_update_mutex ) ; } thermal_zone_device_unregister ( aux_entry -> tzone ) ; } } 